<template>
  <ManagementShell><section class="grid gap-4"><header><p class="bm-kicker">Atendimento</p><h1 class="mt-2 font-display text-3xl font-black uppercase">Suporte</h1></header><form class="bm-panel grid gap-3 rounded-md p-4" @submit.prevent="create"><input v-model="form.subject" class="bm-admin-field" minlength="5" placeholder="Assunto" required><textarea v-model="form.message" class="bm-admin-field min-h-28" minlength="10" placeholder="Descreva sua solicitacao" required/><div class="flex justify-end"><button class="bm-admin-primary" type="submit">Abrir ticket</button></div></form><p v-if="message" class="text-sm font-bold text-ember">{{ message }}</p><article v-for="ticket in tickets" :key="ticket.id" class="bm-panel rounded-md p-4"><div class="flex items-center justify-between gap-3"><strong>{{ ticket.subject }}</strong><span class="bm-admin-chip">{{ ticket.status }}</span></div><p class="mt-2 text-sm text-white/58">{{ ticket.message }}</p></article></section></ManagementShell>
</template>
<script setup lang="ts">import type{SupportTicket}from'~/composables/useSupportApi';const api=useSupportApi();const tickets=ref<SupportTicket[]>([]);const message=ref('');const form=reactive({subject:'',message:'',category:'SUPPORT'});const load=async()=>{try{tickets.value=await api.ownTickets()}catch{tickets.value=[]}};const create=async()=>{try{await api.createTicket(form);Object.assign(form,{subject:'',message:'',category:'SUPPORT'});message.value='Ticket aberto com sucesso.';await load()}catch{message.value='Nao foi possivel abrir o ticket.'}};onMounted(load);useSeoMeta({title:'Suporte'})</script>
